import { useEffect, useRef, useState } from "react";
import { extractErrorMessage } from "../api/axios";

export function useLookupOptions(fetchFn, mapper) {
  const [options, setOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  // Keep the latest functions without making the effect
  // run again every time the component renders.
  const fetchFnRef = useRef(fetchFn);
  const mapperRef = useRef(mapper);

  useEffect(() => {
    fetchFnRef.current = fetchFn;
  }, [fetchFn]);

  useEffect(() => {
    mapperRef.current = mapper;
  }, [mapper]);

  useEffect(() => {
    let isCurrent = true;

    async function loadOptions() {
      setIsLoading(true);
      setError("");

      try {
        const response = await fetchFnRef.current();

        if (!isCurrent) return;

        const data = response?.data;

        let list = [];

        // API returns:
        // [...]
        if (Array.isArray(data)) {
          list = data;
        }

        // API returns:
        // { data: [...] }
        else if (Array.isArray(data?.data)) {
          list = data.data;
        }

        // API returns:
        // { students: [...] }
        else if (Array.isArray(data?.students)) {
          list = data.students;
        }

        // API returns:
        // { courses: [...] }
        else if (Array.isArray(data?.courses)) {
          list = data.courses;
        }

        // API returns:
        // { departments: [...] }
        else if (Array.isArray(data?.departments)) {
          list = data.departments;
        }

        // API returns:
        // { items: [...] }
        else if (Array.isArray(data?.items)) {
          list = data.items;
        }

        // API returns:
        // { data: { students: [...] } }
        else if (Array.isArray(data?.data?.students)) {
          list = data.data.students;
        }

        // API returns:
        // { data: { courses: [...] } }
        else if (Array.isArray(data?.data?.courses)) {
          list = data.data.courses;
        }

        // API returns:
        // { data: { departments: [...] } }
        else if (Array.isArray(data?.data?.departments)) {
          list = data.data.departments;
        }

        const mappedOptions = list
          .map((item) => {
            try {
              return mapperRef.current(item);
            } catch (error) {
              console.error("Lookup mapper error:", error);
              return null;
            }
          })
          .filter(
            (option) =>
              option &&
              option.value !== undefined &&
              option.value !== null
          );

        if (isCurrent) {
          setOptions(mappedOptions);
        }
      } catch (err) {
        if (!isCurrent) return;

        setOptions([]);

        setError(
          extractErrorMessage(
            err,
            "Unable to load options."
          )
        );
      } finally {
        if (isCurrent) {
          setIsLoading(false);
        }
      }
    }

    loadOptions();

    return () => {
      isCurrent = false;
    };
  }, []);

  return {
    options,
    isLoading,
    error
  };
}
